/**
 * The dissertation's bibliography — the original 2004 reference list, modernized.
 *
 * Transcribed from the manuscript and restandardized to APA 7th: working papers
 * and preprints that were later published carry their final publication details,
 * DOIs have been resolved where one exists, and the entries mutilated in the
 * printed copy (original pages 254-256 and 274-275) have been reconstructed.
 *
 * `r` is everything after the year. A pair of asterisks marks italics — the
 * work's own title, or the journal it ran in — and `renderSegments` below is the
 * only thing that reads them, so no markup is ever injected into the page.
 */

export type Reference = {
  /** Position in the alphabetical list, 1-353. Stable: it is how the page cites. */
  n: number;
  /** Authors, as APA sets them, including an "(Eds.)." where the work is edited. */
  a: string;
  /** Year, occasionally with a month ("1999, June") for a conference paper. */
  y: string;
  /** The rest of the entry: title, container, volume, pages. `*...*` is italic. */
  r: string;
  /** Resolved DOI, or a publisher URL where no DOI exists. Null for 63 entries. */
  doi: string | null;
  /** First author's surname, folded to ASCII lower case: the sort and index key. */
  s: string;
};

