/** Split a reference's text on its asterisk pairs, so italics render as <em>. */
export function renderSegments(text: string): { t: string; em: boolean }[] {
  return text
    .split('*')
    .map((t, i) => ({ t, em: i % 2 === 1 }))
    .filter((seg) => seg.t !== '');
}

/** Everything a search box should look at, lower-cased once per entry. */
export function haystack(ref: Reference): string {
  return `${ref.a} ${ref.y} ${ref.r}`.replace(/\*/g, '').toLowerCase();
}
